using System.Collections.Generic;
using UnityEngine;

namespace AntColony.UI
{
    // 장수 머리 위 하는 일 아이콘. 에셋 없이 12×12 픽셀 패턴으로 만든다('#' = 칠함). 에셋이 생기면 Get()만 바꾸면 된다.
    public static class ActivityIcons
    {
        private static readonly Dictionary<string, (Color color, string[] rows)> Patterns = new Dictionary<string, (Color, string[])>
        {
            ["채집"] = (new Color(.85f, .7f, .45f), new[] { "............", ".#######....", "#.......#...", "......##....", ".....#.#....", "....#..#....", "...#........", "..#.........", ".#..........", "#...........", "............", "............" }), // 곡괭이
            ["건설"] = (new Color(.95f, .75f, .3f), new[] { "............", "..######....", "..######....", "..######....", ".....##.....", ".....##.....", ".....##.....", ".....##.....", ".....##.....", ".....##.....", "............", "............" }), // 망치
            ["농사"] = (new Color(.5f, .9f, .4f), new[] { "............", ".##....##...", "..##..##....", "...####.....", ".....#......", ".....#......", ".....#......", ".....#......", "..#######...", ".#########..", "............", "............" }), // 새싹
            ["낚시"] = (new Color(.45f, .8f, .95f), new[] { "............", "............", "....####..#.", "..########.#", ".##.#######.", "..########.#", "....####..#.", "............", "............", "............", "............", "............" }), // 물고기
            ["제작"] = (new Color(.8f, .8f, .85f), new[] { "............", ".....##.....", "..#.####.#..", "...######...", "..###..###..", ".###....###.", ".###....###.", "..###..###..", "...######...", "..#.####.#..", ".....##.....", "............" }), // 톱니
            ["연구"] = (new Color(.7f, .6f, 1f), new[] { "............", "....####....", ".....##.....", ".....##.....", ".....##.....", "....####....", "...######...", "..########..", ".##########.", ".##########.", "............", "............" }), // 플라스크
            ["휴식"] = (new Color(.75f, .85f, 1f), new[] { "............", ".....#####..", "........#...", ".......#....", "......#####.", ".####.......", "....#.......", "...#........", "..#.........", ".####.......", "............", "............" }), // Zz
            ["수면"] = (new Color(.53f, .66f, .9f), new[] { "............", ".....#####..", "........#...", ".......#....", "......#####.", ".####.......", "....#.......", "...#........", "..#.........", ".####.......", "............", "............" }), // Zz(밤빛)
            ["치료"] = (new Color(1f, .45f, .45f), new[] { "............", "....####....", "....####....", "....####....", ".##########.", ".##########.", ".##########.", "....####....", "....####....", "....####....", "............", "............" }), // 십자
            ["출전"] = (new Color(1f, .6f, .35f), new[] { "..........#.", ".........##.", "........##..", ".......##...", "......##....", ".#...##.....", "..#.##......", "...##.......", "..#.#.......", ".#...#......", "#...........", "............" }), // 검
            ["귀환"] = (new Color(.6f, .9f, .7f), new[] { "............", "....#.......", "...##.......", "..#######...", ".########...", "..#######...", "...##...#...", "....#...#...", "........#...", "....#####...", "............", "............" }), // 되돌아가는 화살표
            ["붕괴"] = (new Color(.85f, .3f, .95f), new[] { "............", "..##....##..", ".#..#..#..#.", ".#..#..#..#.", "..##....##..", "............", "....####....", "...#....#...", "..#......#..", "............", "............", "............" }), // 괴로운 얼굴
        };
        static ActivityIcons()
        {
            Patterns["간호"] = Patterns["치료"]; Patterns["수리"] = Patterns["건설"]; Patterns["운반"] = Patterns["채집"];
            Patterns["사냥"] = Patterns["출전"]; Patterns["요리"] = Patterns["연구"]; Patterns["예술"] = Patterns["제작"]; Patterns["정치"] = Patterns["연구"]; Patterns["사육"] = Patterns["농사"];
            Patterns["치우기"] = Patterns["운반"]; Patterns["동족 포식"] = Patterns["채집"];
        }
        private static readonly Dictionary<string, Texture2D> Cache = new Dictionary<string, Texture2D>();

        public static IEnumerable<string> Names => Patterns.Keys;

        public static Texture2D Get(string activity)
        {
            if (string.IsNullOrEmpty(activity) || !Patterns.TryGetValue(activity, out var p)) return null;
            if (Cache.TryGetValue(activity, out var cached) && cached != null) return cached;
            var tex = new Texture2D(12, 12, TextureFormat.RGBA32, false) { filterMode = FilterMode.Point, name = "Icon " + activity };
            for (var y = 0; y < 12; y++)
                for (var x = 0; x < 12; x++)
                    tex.SetPixel(x, 11 - y, p.rows[y][x] == '#' ? p.color : Color.clear);
            tex.Apply();
            return Cache[activity] = tex;
        }
    }
}
